const utmParams = new URLSearchParams();
for (const utm_key of utm_keys) {
    const utm_val = urlParams.get(utm_key); // ignore if has empty
    if (utm_val)
        utmParams.append(utm_key, utm_val);
}
const utm = utmParams.toString();
if (utm.length) {
